def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1,)

        key = [0]  # Pre-release sorts before no pre-release
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers sort numerically and before non-digit
                key.append((0, int(identifier)))
            else:
                # Non-digit identifiers sort by ASCII
                key.append((1, identifier))
        return tuple(key)

    def sort_key(item):
        version_str, index = item
        major, minor, patch, prerelease_ids = parse_version(version_str)
        return (major, minor, patch, prerelease_key(prerelease_ids), index)

    # Add original index to maintain stable sort
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for v, _ in sorted_versions]

